def longestBalancedSubarray(nums):
    n = len(nums)
    max_len = 0

    # Try every possible subarray
    for i in range(n):
        even_set = set()
        odd_set = set()
        for j in range(i, n):
            if nums[j] % 2 == 0:
                even_set.add(nums[j])
            else:
                odd_set.add(nums[j])
            # Check if balanced
            if len(even_set) == len(odd_set) and len(even_set) > 0:
                max_len = max(max_len, j - i + 1)
    return max_len
